    // =========================================
    // GET ALL ORDERS
    // =========================================

    const getAllOrdersReducer =
        useSelector(
            state => state.getAllOrdersReducer
        )

    const {
        orders = [],
        loading: loadingOrders
    } = getAllOrdersReducer


    // =========================================
    // DELIVERY STATUS REDUCER
    // =========================================

    const changeDeliveryStatusReducer =
        useSelector(
            state => state.changeDeliveryStatusReducer
        )

    const {
        success: deliveryStatusChangeSuccess,
        loading: deliveryStatusChangeSpinner
    } = changeDeliveryStatusReducer


    // =========================================
    // TOKEN VALIDATION
    // =========================================

    const checkTokenValidationReducer =
        useSelector(
            state => state.checkTokenValidationReducer
        )

    const {
        error: tokenError
    } = checkTokenValidationReducer


    // =========================================
    // GET ORDERS
    // =========================================

    useEffect(() => {

        if (!userInfo) {

            history.push("/login")

        } else {

            dispatch(
                checkTokenValidation()
            )

            dispatch(
                getAllOrders()
            )

        }

    }, [
        userInfo,
        dispatch,
        history
    ])


    // =========================================
    // SESSION EXPIRED
    // =========================================

    useEffect(() => {

        if (
            userInfo &&
            tokenError ===
            "Request failed with status code 401"
        ) {

            alert(
                "Session expired, please login again."
            )

            dispatch(
                logout()
            )

            history.push("/login")

            window.location.reload()

        }

