    // CHANGE DELIVERY STATUS
    // =========================================

    const changeDeliveryStatusHandler =
        (id, status) => {

            setIdOfchangeDeliveryStatus(id)

            const productData = {

                is_delivered: status,

                delivered_at:
                    status
                        ? currentDateInfo
                        : "Not Delivered"

            }

            dispatch(
                changeDeliveryStatus(
                    id,
                    productData
                )
            )

        }


    // =========================================
    // DELIVERY SUCCESS
    // =========================================

    useEffect(() => {

        if (deliveryStatusChangeSuccess) {

            alert(
                "Delivery status changed successfully"
            )

            dispatch({
                type:
                    CHANGE_DELIVERY_STATUS_RESET
            })

            dispatch(
                getAllOrders()
            )

        }

    }, [
        deliveryStatusChangeSuccess,
        dispatch
    ])


    // =========================================
    // SEARCH
    // =========================================

    const handleSearchTerm = (term) => {

        setCloneSearchTerm(
            term.toLowerCase()
        )

    }


    // =========================================
    // FILTER ORDERS
    // =========================================

    const filteredOrders =
        orders.filter((item) => {

            return (

                (item.name || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

                ||

                (item.ordered_item || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

                ||

                (item.address || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

            )

        })


