                    <p>
                        Manage and track customer orders
                    </p>

                </div>

                <div className="orders-count">

                    <strong>
                        {filteredOrders.length}
                    </strong>

                    <span>
                        Orders
                    </span>

                </div>

            </div>


            {/* =================================
                LOADING
            ================================= */}

            {loadingOrders && (

                <div className="orders-loading">

                    <Spinner
                        animation="border"
                        size="sm"
                    />

                    <h5>
                        Getting Orders...
                    </h5>

                </div>

            )}


            {/* =================================
                SEARCH
            ================================= */}

            {userInfo &&
                userInfo.admin && (

                    <div className="orders-search">

                        <SearchBarForOrdersPage

                            handleSearchTerm={
                                handleSearchTerm
                            }

                            placeholderValue={
                                placeholderValue
                            }

                        />

                    </div>

                )
            }


            {/* =================================
                ORDERS TABLE
            ================================= */}

            {filteredOrders.length > 0 ? (

                <div className="orders-table-container">

                    <Table
                        className="orders-table"
                        responsive
                    >

                        <thead>

                            <tr>

                                <th>
                                    Order ID
                                </th>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Card
                                </th>

                                <th>
                                    Delivery Address
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Payment
                                </th>

                                <th>
                                    Paid On
                                </th>

                                <th>
                                    Amount
                                </th>

                                <th>
                                    Delivery
                                </th>

